// The Worker wrangler deploys: OpenNext's (.open-next/worker.js, generated by
// `opennextjs-cloudflare build`) with Auth.js's signing key handed to it in
// the environment — the owner's AUTH_SECRET, or the key this environment
// generated for itself (lib/auth-secret.ts). The Durable Object classes the
// cache uses are OpenNext's, re-exported. Excluded from tsc and eslint: the
// module it wraps exists only after a build.
// @ts-ignore generated by the build
import handler from './.open-next/worker.js';
import { authSecret } from './lib/auth-secret';

// @ts-ignore generated by the build
export { DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js';

interface Env {
  AUTH_SECRET?: string;
  CATALYST_ROUTES_KV?: {
    get(key: string): Promise<string | null>;
    put(key: string, value: string): Promise<void>;
  };
  [binding: string]: unknown;
}

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const secret = await authSecret(env.AUTH_SECRET, env.CATALYST_ROUTES_KV);

    return handler.fetch(request, secret ? { ...env, AUTH_SECRET: secret } : env, ctx);
  },
};
